#include <iostream>
#include <string>
using namespace std;

class Pizza {
public:
    string size;
    bool cheese, pepperoni, mushrooms, olives;
    void describe() {
        cout << size << " pizza with";
        if (cheese) cout << " cheese";
        if (pepperoni) cout << " pepperoni";
        cout << endl;
    }
};

class PizzaBuilder {
    Pizza pizza;
public:
    PizzaBuilder& setSize(const string& s) { pizza.size = s; return *this; }
    PizzaBuilder& addCheese() { pizza.cheese = true; return *this; }
    PizzaBuilder& addPepperoni() { pizza.pepperoni = true; return *this; }
    Pizza build() {
        Pizza p = pizza;
        pizza = Pizza(); // reset
        return p;
    }
};

int main() {
    Pizza p = PizzaBuilder().setSize("Large").addCheese().addPepperoni().build();
    p.describe();
    return 0;
}
